public class Point
{
    public int X { get; }
    public int Y { get; }

    public Point(int x, int y) => (X, Y) = (x, y);   // 构造函数

    public double Length => Math.Sqrt(X * X + Y * Y);  // 只读属性

    public override string ToString() => $"({X}, {Y})"; // 方法

    public double DistanceTo(Point other) =>
        Math.Sqrt(Math.Pow(X - other.X, 2) + Math.Pow(Y - other.Y, 2));
}

