public byte[] Process(int size)
{
    var pool = ArrayPool<byte>.Shared;
    byte[] buffer = pool.Rent(size);       // 租借 ≥ size 的数组
    try
    {
        Array.Clear(buffer, 0, size);      // 内容是脏的，先清零
        // ... 使用 buffer.AsSpan(0, size) ...
        return buffer[..size].ToArray();   // 只复制实际长度
    }
    finally
    {
        pool.Return(buffer);               // 必须归还（放 finally）
    }
}

